                                {showPeerSync && (
                                    <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md rounded-3xl overflow-hidden flex items-center justify-center p-4 sm:p-6 z-30 animate-in fade-in zoom-in-95 duration-500">
                                        <PeerSyncRadar 
                                            courseId={course.id} 
                                            moduleId={activeMidRollSync ? `${activeVideo.id}_${activeMidRollSync.id}` : activeVideo.id} 
                                            user={user}
                                            course={course}
                                            activeVideo={activeVideo}
                                            activeMidRollSync={activeMidRollSync}
                                            onCheckpointCleared={() => {
                                                setShowPeerSync(false);
                                                if (activeMidRollSync) {
                                                    // Mid-roll sync cleared: resume video!
                                                    playerRef.play();
                                                    addToast("Checkpoint cleared! Resuming video...", "success");
                                                } else {
                                                    // End-of-lesson sync cleared: complete lesson!
                                                    markLessonAsCompleted(activeVideo.id);
                                                }
                                                setActiveMidRollSync(null);
                                            }} 
                                            onAsyncOptIn={handleAsyncOptIn}
                                        />
                                    </div>
                                )}

