import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { addNoteAsync, deleteNoteAsync, updateNoteAsync } from '../../../store/activitySlice';
import { cn } from '../../../utils/cn';

const CourseNotebook = ({ courseId, lessonId, currentTime, onSeek }) => {
    const dispatch = useDispatch();
    const notes = useSelector(state => state.activity.notes[courseId] || []);
    const [noteText, setNoteText] = useState('');
    const [editingNoteId, setEditingNoteId] = useState(null);
    const [editText, setEditText] = useState('');

    const formatTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    const handleAddNote = (e) => {
        e.preventDefault();
        if (!noteText.trim()) return;

        dispatch(addNoteAsync({
            courseId,
            lessonId,
            timestamp: currentTime,
            content: noteText.trim()
        }));
        setNoteText('');
    };

    const handleUpdate = (noteId) => {
        if (!editText.trim()) return;
        dispatch(updateNoteAsync({ courseId, noteId, content: editText.trim() }));
        setEditingNoteId(null);
    };

    return (
        <div className="flex flex-col h-[60vh]">
            {/* Input Area */}
            <form onSubmit={handleAddNote} className="p-4 border-b border-border bg-muted/5">
                <div className="relative">
                    <textarea
                        value={noteText}
                        onChange={(e) => setNoteText(e.target.value)}
                        placeholder="Type a note at this moment..."
                        className="w-full bg-background border border-border rounded-2xl p-4 pr-12 text-sm focus:ring-2 focus:ring-secondary/20 focus:border-secondary outline-none transition-all resize-none h-24"
                    />
                    <div className="absolute bottom-3 right-3 flex items-center gap-2">
                        <span className="text-[10px] font-bold text-secondary bg-secondary/10 px-2 py-0.5 rounded-md">
                            {formatTime(currentTime)}
                        </span>
                        <button
                            type="submit"
                            disabled={!noteText.trim()}
                            className="w-8 h-8 rounded-full bg-secondary text-white flex items-center justify-center hover:scale-110 active:scale-95 transition-all disabled:opacity-50 disabled:scale-100"
                        >
                            <Icon name="Plus" size={16} />
                        </button>
                    </div>
                </div>
            </form>

            {/* Notes List */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {notes.length > 0 ? (
                    notes.map((note) => (
                        <div key={note.id} className="group bg-muted/20 border border-border rounded-2xl p-4 hover:border-secondary/30 transition-all">
                            <div className="flex items-center justify-between mb-2">
                                <button
                                    onClick={() => onSeek(note.timestamp)}
                                    className="flex items-center gap-1.5 text-[10px] font-black italic text-secondary hover:text-primary transition-colors bg-secondary/10 px-2 py-1 rounded-lg"
                                >
                                    <Icon name="Play" size={10} fill="currentColor" />
                                    {formatTime(note.timestamp)}
                                </button>
                                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button
                                        onClick={() => {
                                            setEditingNoteId(note.id);
                                            setEditText(note.content);
                                        }}
                                        className="p-1.5 text-muted-foreground hover:text-primary transition-colors"
                                    >
                                        <Icon name="Edit2" size={12} />
                                    </button>
                                    <button
                                        onClick={() => dispatch(deleteNoteAsync({ courseId, noteId: note.id }))}
                                        className="p-1.5 text-muted-foreground hover:text-destructive transition-colors"
                                    >
                                        <Icon name="Trash2" size={12} />
                                    </button>
                                </div>
                            </div>

                            {editingNoteId === note.id ? (
                                <div className="space-y-2">
                                    <textarea
                                        value={editText}
                                        onChange={(e) => setEditText(e.target.value)}
                                        className="w-full bg-background border border-border rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-secondary/20"
                                        autoFocus
                                    />
                                    <div className="flex justify-end gap-2">
                                        <Button size="sm" variant="ghost" onClick={() => setEditingNoteId(null)}>Cancel</Button>
                                        <Button size="sm" onClick={() => handleUpdate(note.id)}>Save</Button>
                                    </div>
                                </div>
                            ) : (
                                <p className="text-sm text-primary leading-relaxed whitespace-pre-wrap">
                                    {note.content}
                                </p>
                            )}
                            <div className="mt-2 text-[9px] text-muted-foreground font-medium uppercase tracking-wider">
                                {new Date(note.date).toLocaleDateString()} at {new Date(note.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </div>
                        </div>
                    ))
                ) : (
                    <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-40">
                        <div className="w-16 h-16 bg-muted rounded-full flex items-center justify-center mb-4">
                            <Icon name="StickyNote" size={32} />
                        </div>
                        <p className="text-sm font-bold text-primary">Your Notebook is Empty</p>
                        <p className="text-xs text-muted-foreground">Take notes to capture key insights from the lesson!</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default CourseNotebook;
