import React, { useState, useEffect, useCallback } from 'react';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { useToast } from '../../../contexts/ToastContext';
import { detectContactSharing, CONTACT_GUARD_MESSAGE } from '../../../utils/contactGuard';

const ProctoredExam = ({ isOpen, onClose, courseTitle, onComplete }) => {
    const { addToast } = useToast();
    const [started, setStarted] = useState(false);
    const [timeLeft, setTimeLeft] = useState(45 * 60); // 45 minutes
    const [warnings, setWarnings] = useState(0);
    const [examFailed, setExamFailed] = useState(false);
    
    // Mock questions for the UI (12 objective, 8 open-ended)
    const [answers, setAnswers] = useState({});

    // Prevent tab switching (Self-Proctoring Core Logic)
    useEffect(() => {
        if (!started || examFailed) return;

        const handleVisibilityChange = () => {
            if (document.hidden) {
                setWarnings(prev => {
                    const newWarnings = prev + 1;
                    if (newWarnings >= 3) {
                        setExamFailed(true);
                        addToast("EXAM TERMINATED: You left the exam window too many times.", "error");
                    } else {
                        addToast(`WARNING (${newWarnings}/3): Do not leave the exam window!`, "warning");
                    }
                    return newWarnings;
                });
            }
        };

        // Prevent copying and pasting
        const handleCopyPaste = (e) => {
            e.preventDefault();
            addToast("Copy/Paste is disabled during proctored exams.", "error");
        };

        document.addEventListener("visibilitychange", handleVisibilityChange);
        document.addEventListener("copy", handleCopyPaste);
        document.addEventListener("paste", handleCopyPaste);

        return () => {
            document.removeEventListener("visibilitychange", handleVisibilityChange);
            document.removeEventListener("copy", handleCopyPaste);
            document.removeEventListener("paste", handleCopyPaste);
        };
    }, [started, examFailed, addToast]);

    // Timer Logic
    useEffect(() => {
        if (!started || examFailed || timeLeft <= 0) return;

        const timer = setInterval(() => {
            setTimeLeft(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    handleSubmit();
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(timer);
    }, [started, examFailed, timeLeft]);

    const formatTime = (seconds) => {
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}:${s.toString().padStart(2, '0')}`;
    };

    const handleStart = async () => {
        try {
            // Request Fullscreen
            if (document.documentElement.requestFullscreen) {
                await document.documentElement.requestFullscreen();
            }
        } catch (err) {
            console.log("Fullscreen request failed", err);
        }
        setStarted(true);
        addToast("Exam started. Good luck!", "info");
    };

    const handleSubmit = () => {
        for (let i = 0; i < 8; i++) {
            const answer = answers[`open-${i}`] || '';
            const guard = detectContactSharing(answer);
            if (guard.blocked) {
                addToast(`Question ${12 + i + 1}: ${CONTACT_GUARD_MESSAGE}`, "error");
                return;
            }
        }

        if (document.fullscreenElement) {
            document.exitFullscreen().catch(err => console.log(err));
        }
        addToast("Exam submitted for grading!", "success");
        onComplete(answers);
    };

    const handleQuit = () => {
        if (document.fullscreenElement) {
            document.exitFullscreen().catch(err => console.log(err));
        }
        onClose();
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] bg-slate-950 flex flex-col overflow-hidden">
            {/* Strict Exam Header */}
            <header className="bg-slate-900 border-b border-red-500/20 px-6 py-4 flex items-center justify-between shrink-0">
                <div className="flex items-center gap-4">
                    <div className="flex items-center justify-center w-10 h-10 rounded-full bg-red-500/10 text-red-500">
                        <Icon name="ShieldAlert" size={20} />
                    </div>
                    <div>
                        <h1 className="text-lg font-black text-white italic">Self-Proctored Final Exam</h1>
                        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{courseTitle}</p>
                    </div>
                </div>

                {started && !examFailed && (
                    <div className="flex items-center gap-6">
                        <div className="flex flex-col items-end">
                            <span className="text-[10px] font-black uppercase tracking-widest text-red-400">Warnings</span>
                            <div className="flex gap-1 mt-1">
                                {[1, 2, 3].map(w => (
                                    <div key={w} className={`w-3 h-3 rounded-full ${warnings >= w ? 'bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-slate-800'}`} />
                                ))}
                            </div>
                        </div>
                        <div className="bg-black/50 border border-white/10 px-4 py-2 rounded-xl flex items-center gap-3">
                            <Icon name="Clock" size={16} className={timeLeft < 300 ? 'text-red-500 animate-pulse' : 'text-slate-400'} />
                            <span className={`text-xl font-black tabular-nums ${timeLeft < 300 ? 'text-red-500' : 'text-white'}`}>
                                {formatTime(timeLeft)}
                            </span>
                        </div>
                        <Button variant="default" size="sm" onClick={handleSubmit} className="bg-brand-blue hover:bg-brand-blue/80 text-white font-black italic">
                            SUBMIT EXAM
                        </Button>
                    </div>
                )}
            </header>

            {/* Main Content Area */}
            <main className="flex-1 overflow-y-auto p-6 md:p-12 relative">
                {!started && !examFailed ? (
                    <div className="max-w-2xl mx-auto mt-20 bg-slate-900 border border-white/10 rounded-3xl p-8 text-center shadow-2xl">
                        <Icon name="Eye" size={48} className="text-brand-blue mx-auto mb-6" />
                        <h2 className="text-3xl font-black text-white italic mb-4">Exam Protocol Active</h2>
                        
                        <div className="text-left bg-black/40 border border-white/5 rounded-2xl p-6 mb-8 space-y-4">
                            <p className="text-sm text-slate-300">By starting this exam, you agree to the LUC Academy Honor Code. This is a rigorous assessment consisting of:</p>
                            <ul className="text-sm text-slate-300 list-disc pl-5 font-bold space-y-1">
                                <li className="text-white">12 Objective Questions</li>
                                <li className="text-white">8 Open-Ended Synthesis Questions</li>
                            </ul>
                            
                            <div className="mt-6 pt-6 border-t border-white/10 space-y-3">
                                <div className="flex items-center gap-3 text-red-400">
                                    <Icon name="AlertTriangle" size={16} />
                                    <span className="text-xs font-bold uppercase tracking-widest">Strict Proctoring Rules:</span>
                                </div>
                                <p className="text-xs text-slate-400 pl-7">- Leaving the exam tab/window will trigger a strike. 3 strikes = Auto-Fail.</p>
                                <p className="text-xs text-slate-400 pl-7">- Copying and pasting is globally disabled.</p>
                                <p className="text-xs text-slate-400 pl-7">- Sharing phone numbers, emails, or WhatsApp in answers is prohibited.</p>
                                <p className="text-xs text-slate-400 pl-7">- All answers must be submitted on-platform.</p>
                            </div>
                        </div>

                        <div className="flex gap-4 justify-center">
                            <Button variant="ghost" onClick={handleQuit}>Cancel</Button>
                            <Button size="lg" className="bg-brand-blue hover:bg-brand-blue/80 text-white font-black italic shadow-lg shadow-brand-blue/20" onClick={handleStart}>
                                I AGREE, START EXAM
                            </Button>
                        </div>
                    </div>
                ) : examFailed ? (
                    <div className="max-w-2xl mx-auto mt-20 bg-red-950/30 border border-red-500/30 rounded-3xl p-8 text-center shadow-2xl">
                        <Icon name="XOctagon" size={64} className="text-red-500 mx-auto mb-6" />
                        <h2 className="text-3xl font-black text-white italic mb-4">Exam Terminated</h2>
                        <p className="text-slate-400 mb-8">You have violated the exam protocol by navigating away from the window too many times. This attempt has been recorded as a failure.</p>
                        <Button size="lg" variant="outline" className="border-red-500/50 text-red-500 hover:bg-red-500/10 font-black italic" onClick={handleQuit}>
                            RETURN TO COURSE
                        </Button>
                    </div>
                ) : (
                    <div className="max-w-4xl mx-auto space-y-12 pb-24">
                        {/* Section 1: Objectives */}
                        <section className="space-y-6">
                            <div className="border-b border-white/10 pb-4 mb-8">
                                <h3 className="text-2xl font-black text-white italic">Part I: Objective Analysis</h3>
                                <p className="text-sm text-slate-400">Select the most accurate strategic approach.</p>
                            </div>

                            {[...Array(12)].map((_, i) => (
                                <div key={`obj-${i}`} className="bg-slate-900 border border-white/5 rounded-2xl p-6">
                                    <p className="text-white font-bold mb-4"><span className="text-brand-blue mr-2">Q{i + 1}.</span> Based on the framework discussed in Module 3, which approach mitigates scaling risks the fastest?</p>
                                    <div className="space-y-3">
                                        {['Horizontal sharding of the database layer.', 'Vertical scaling of the primary instance.', 'Implementing a strict microservices architecture.', 'Caching aggressively at the edge.'].map((opt, oIdx) => (
                                            <label key={oIdx} className="flex items-start gap-3 p-4 rounded-xl border border-white/5 hover:bg-white/5 cursor-pointer transition-colors has-[:checked]:bg-brand-blue/10 has-[:checked]:border-brand-blue/30">
                                                <input 
                                                    type="radio" 
                                                    name={`q-${i}`} 
                                                    className="mt-1 accent-brand-blue"
                                                    onChange={() => setAnswers(prev => ({ ...prev, [`obj-${i}`]: oIdx }))}
                                                />
                                                <span className="text-sm text-slate-300 leading-relaxed">{opt}</span>
                                            </label>
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </section>

                        {/* Section 2: Open-Ended */}
                        <section className="space-y-6 pt-12 mt-12 border-t border-white/10">
                            <div className="border-b border-white/10 pb-4 mb-8">
                                <h3 className="text-2xl font-black text-white italic">Part II: Open-Ended Synthesis</h3>
                                <p className="text-sm text-slate-400">Explain your reasoning clearly. Pasting is disabled; type your answers organically.</p>
                            </div>

                            {[...Array(8)].map((_, i) => (
                                <div key={`open-${i}`} className="bg-slate-900 border border-white/5 rounded-2xl p-6">
                                    <p className="text-white font-bold mb-4"><span className="text-secondary mr-2">Q{12 + i + 1}.</span> Describe the trade-offs between monolithic and microservices architecture in the context of a seed-stage startup. Defend your choice.</p>
                                    <textarea 
                                        className="w-full bg-black/40 border border-white/10 rounded-xl p-4 text-sm text-slate-300 focus:outline-none focus:ring-2 focus:ring-secondary/50 min-h-[150px] resize-y"
                                        placeholder="Type your strategic analysis here..."
                                        value={answers[`open-${i}`] || ''}
                                        onChange={(e) => setAnswers(prev => ({ ...prev, [`open-${i}`]: e.target.value }))}
                                        onCopy={(e) => e.preventDefault()}
                                        onCut={(e) => e.preventDefault()}
                                    />
                                    <div className="flex justify-between items-center mt-3">
                                        <span className="text-[10px] text-slate-500 uppercase tracking-widest flex items-center gap-1">
                                            <Icon name="Lock" size={10} /> Keyboard only. No pasting allowed.
                                        </span>
                                        <span className={`text-[10px] font-bold ${answers[`open-${i}`]?.length > 100 ? 'text-emerald-500' : 'text-slate-500'}`}>
                                            {answers[`open-${i}`]?.length || 0} / 500 chars minimum
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </section>
                    </div>
                )}
            </main>
        </div>
    );
};

export default ProctoredExam;
